<?php
declare(strict_types=1);

function report_recommendations(array $pc,array $disks,array $analysis): array {
    $recommendations=[];$status=(string)($pc['asset_status']??'');$inUse=$status==='Em uso';$types=array_column($disks,'disk_type');$hasFast=(bool)array_intersect(['SSD','NVMe'],$types);$hasHdd=in_array('HDD',$types,true);$year=(int)($pc['manufacture_year']??0);$age=$year?(int)date('Y')-$year:0;$ram=(int)($pc['ram_gb']??0);$windows=strtolower((string)($pc['windows_version']??''));
    if($status==='Baixado')return ['Equipamento baixado: evitar novos investimentos e garantir descarte ou destinação segura dos dados e componentes.'];
    if($hasHdd&&!$hasFast)$recommendations[]=$inUse?'Substituir o HD por SSD é uma melhoria de baixo custo que deve reduzir bastante o tempo de inicialização e abertura de programas.':'Antes de voltar este equipamento ao uso, substituir o HD por SSD para melhorar o desempenho.';
    if($inUse&&$age>10)$recommendations[]="Equipamento em uso com aproximadamente {$age} anos: programar sua substituição assim que possível, pois o risco de falha e indisponibilidade é elevado.";
    elseif($age>10)$recommendations[]="Equipamento com aproximadamente {$age} anos: evitar destiná-lo a atividades críticas e planejar sua substituição.";
    if($ram>0&&$ram<=4)$recommendations[]="Ampliar a memória de {$ram} GB para pelo menos 8 GB deve melhorar a navegação, a multitarefa e o uso dos sistemas atuais.";
    elseif($ram>4&&$ram<8)$recommendations[]="Avaliar expansão da memória de {$ram} GB para 8 GB ou mais, conforme a carga de trabalho do usuário.";
    if(str_contains($windows,'windows 7')||str_contains($windows,'windows 8'))$recommendations[]='Sistema operacional sem suporte atual: migrar para uma versão suportada ou substituir o equipamento se ele não for compatível.';
    elseif(str_contains($windows,'windows 10'))$recommendations[]='Validar compatibilidade com Windows 11; se não houver suporte, incluir o equipamento no plano de renovação.';
    if($status==='Reserva'&&$analysis['level']!=='ok')$recommendations[]='Como está em reserva, executar os upgrades e testes antes de disponibilizá-lo novamente para um usuário.';
    if(!$recommendations)$recommendations[]='Sem intervenção urgente identificada; manter atualizações, limpeza preventiva e monitoramento periódico.';
    return $recommendations;
}

function report_action_summary(array $rows): array {
    return [
        'ssd'=>count(array_filter($rows,fn($r)=>$r['_needs_ssd']&&$r['asset_status']==='Em uso')),
        'replace'=>count(array_filter($rows,fn($r)=>$r['_age']>10&&$r['asset_status']==='Em uso')),
        'memory'=>count(array_filter($rows,fn($r)=>(int)$r['ram_gb']>0&&(int)$r['ram_gb']<=4&&$r['asset_status']==='Em uso')),
    ];
}

function report_rows(): array {
    $where=['company_id=?'];$params=[tenant_id()];
    $filters=[
        'sector'=>'sector',
        'user'=>'assigned_user',
        'status'=>'asset_status',
        'windows'=>'windows_version',
    ];
    foreach($filters as $input=>$column){$value=trim((string)($_GET[$input]??''));if($value==='')continue;if($input==='user'){$where[]="$column LIKE ?";$params[]="%$value%";}else{$where[]="$column=?";$params[]=$value;}}
    $pcs=query('SELECT * FROM computers WHERE '.implode(' AND ',$where).' ORDER BY computer_name',$params)->fetchAll();
    $disks=[];if($pcs){$ids=array_column($pcs,'id');$marks=implode(',',array_fill(0,count($ids),'?'));foreach(query("SELECT * FROM disks WHERE computer_id IN ($marks) ORDER BY computer_id,id",$ids)->fetchAll() as $disk)$disks[$disk['computer_id']][]=$disk;}
    $level=trim((string)($_GET['criticality']??''));$rows=[];
    foreach($pcs as $pc){$pcDisks=$disks[$pc['id']]??[];$analysis=criticality($pc,$pcDisks);if($level!==''&&$analysis['level']!==$level)continue;$diskText=[];foreach($pcDisks as $disk)$diskText[]=trim($disk['disk_type'].' '.($disk['brand_model']??'').' '.($disk['size_gb']?($disk['size_gb'].' GB'):''));$types=array_column($pcDisks,'disk_type');$pc['_analysis']=$analysis;$pc['_disks']=implode(' + ',$diskText)?:'Não informado';$pc['_ram_layout']=$pc['ram_sticks_count']&&$pc['ram_per_stick_gb']?$pc['ram_sticks_count'].' × '.$pc['ram_per_stick_gb'].' GB':($pc['ram_slots_detail']?:'Não informado');$pc['_needs_ssd']=in_array('HDD',$types,true)&&!(bool)array_intersect(['SSD','NVMe'],$types);$pc['_age']=$pc['manufacture_year']?(int)date('Y')-(int)$pc['manufacture_year']:0;$pc['_recommendations']=report_recommendations($pc,$pcDisks,$analysis);$rows[]=$pc;}
    return $rows;
}
function report_level_label(string $level): string { return ['critical'=>'Crítico','attention'=>'Atenção','ok'=>'Adequado'][$level]??$level; }
function report_status_class(string $status): string { return $status==='Em uso'?'ok':($status==='Baixado'?'critical':'attention'); }

if($path==='/reports/excel'){
    $rows=report_rows();$filename='inventario-'.preg_replace('/[^a-z0-9_-]+/','-',strtolower((string)(company()['slug']??'empresa'))).'-'.date('Y-m-d').'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['Computador','Setor','Usuário','Situação','Ano','Fabricante','Modelo','Processador','RAM total','Configuração RAM','Windows','Discos','Criticidade','Pontuação','Motivos','Recomendações'],';','"','');foreach($rows as $pc)fputcsv($out,[$pc['computer_name'],$pc['sector'],$pc['assigned_user'],$pc['asset_status'],$pc['manufacture_year'],$pc['manufacturer'],$pc['model'],$pc['processor'],$pc['ram_gb']?($pc['ram_gb'].' GB'):'',$pc['_ram_layout'],$pc['windows_version'],$pc['_disks'],report_level_label($pc['_analysis']['level']),$pc['_analysis']['score'],implode(' | ',$pc['_analysis']['reasons']),implode(' | ',$pc['_recommendations'])],';','"','');fclose($out);exit;
}

if($path==='/reports/pdf'){
    $rows=report_rows();$critical=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='critical'));$attention=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='attention'));$inUse=count(array_filter($rows,fn($r)=>$r['asset_status']==='Em uso'));$actions=report_action_summary($rows);?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório de equipamentos · <?=e(company()['name'])?></title><style>@page{size:A4 landscape;margin:9mm}*{box-sizing:border-box}body{font:9px Arial,sans-serif;color:#182238;margin:0}header{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:3px solid <?=e(company()['primary_color']??'#173F73')?>;padding-bottom:8px;margin-bottom:8px}h1{font-size:20px;margin:0}h2{font-size:13px;margin:8px 0 4px}p{margin:3px 0}.summary{display:flex;gap:7px;margin:8px 0}.summary div{border:1px solid #ccd5e2;border-radius:6px;padding:6px 10px}.summary strong{font-size:14px;display:block}.recommendation-summary{background:#fff8e8;border:1px solid #f0c36b;border-radius:6px;padding:7px 10px;margin-bottom:8px}.recommendation-summary span{margin-right:18px}table{width:100%;border-collapse:collapse}th{background:#eef2f7;text-align:left;font-size:8px}th,td{border:1px solid #d8dee8;padding:4px;vertical-align:top}.critical{color:#b42318;font-weight:bold}.attention{color:#a15c00;font-weight:bold}.ok{color:#087443;font-weight:bold}.muted{color:#64748b}.recommendation{color:#3c2b00}footer{margin-top:8px;text-align:right;color:#64748b}@media print{button{display:none}}</style></head><body><header><div><h1>Relatório de equipamentos</h1><p><?=e(company()['name'])?></p></div><div>Emitido em <?=date('d/m/Y H:i')?></div></header><div class="summary"><div><strong><?=count($rows)?></strong>equipamentos</div><div><strong><?=$inUse?></strong>em uso</div><div><strong class="critical"><?=$critical?></strong>críticos</div><div><strong class="attention"><?=$attention?></strong>em atenção</div></div><div class="recommendation-summary"><strong>Prioridades identificadas:</strong> <span><?=$actions['ssd']?> em uso precisam de SSD</span><span><?=$actions['memory']?> em uso precisam de mais memória</span><span><?=$actions['replace']?> em uso têm mais de 10 anos</span></div><table><thead><tr><th>Computador</th><th>Setor / usuário</th><th>Situação</th><th>Ano</th><th>Processador</th><th>RAM</th><th>Windows / discos</th><th>Criticidade</th><th>Recomendações</th></tr></thead><tbody><?php foreach($rows as $pc):?><tr><td><strong><?=e($pc['computer_name'])?></strong><br><span class="muted"><?=e(trim(($pc['manufacturer']??'').' '.($pc['model']??'')))?></span></td><td><?=e($pc['sector'])?><br><?=e($pc['assigned_user'])?></td><td class="<?=report_status_class($pc['asset_status'])?>"><?=e($pc['asset_status'])?></td><td><?=e($pc['manufacture_year'])?><?=$pc['_age']?' ('.$pc['_age'].' anos)':''?></td><td><?=e($pc['processor'])?></td><td><?=e(($pc['ram_gb']?:'—').' GB')?><br><span class="muted"><?=e($pc['_ram_layout'])?></span></td><td><?=e($pc['windows_version'])?><br><span class="muted"><?=e($pc['_disks'])?></span></td><td class="<?=e($pc['_analysis']['level'])?>"><?=e(report_level_label($pc['_analysis']['level']))?> (<?=$pc['_analysis']['score']?>)<br><span class="muted"><?=e(implode(' · ',$pc['_analysis']['reasons'])?:'Sem alertas')?></span></td><td class="recommendation"><?=e(implode(' · ',$pc['_recommendations']))?></td></tr><?php endforeach?></tbody></table><footer>Inventário Amplificati · <?=count($rows)?> registro(s)</footer><script>addEventListener('load',()=>setTimeout(()=>print(),300))</script></body></html><?php exit;
}

if($path==='/reports'){
    $rows=report_rows();$critical=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='critical'));$attention=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='attention'));$adequate=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='ok'));$inUse=count(array_filter($rows,fn($r)=>$r['asset_status']==='Em uso'));$actions=report_action_summary($rows);$sectors=query("SELECT name FROM catalog_items WHERE company_id=? AND catalog_type='sector' AND active=1 ORDER BY name",[tenant_id()])->fetchAll(PDO::FETCH_COLUMN);$statuses=query("SELECT name FROM catalog_items WHERE company_id=? AND catalog_type='asset_status' AND active=1 ORDER BY name",[tenant_id()])->fetchAll(PDO::FETCH_COLUMN);$windows=query("SELECT name FROM catalog_items WHERE company_id=? AND catalog_type='windows_version' AND active=1 ORDER BY name",[tenant_id()])->fetchAll(PDO::FETCH_COLUMN);$query=$_GET;$exportQuery=http_build_query($query);page_start('Relatórios','reports');?><div class="grid kpis"><div class="card kpi"><strong><?=count($rows)?></strong><span>No relatório</span></div><div class="card kpi"><strong><?=$inUse?></strong><span>Em uso</span></div><div class="card kpi critical"><strong><?=$critical?></strong><span>Críticos</span></div><div class="card kpi attention"><strong><?=$attention?></strong><span>Em atenção</span></div><div class="card kpi ok"><strong><?=$adequate?></strong><span>Adequados</span></div></div><form class="filters card" method="get"><div class="field"><label>Setor</label><select name="sector"><option value="">Todos</option><?php foreach($sectors as $value):?><option <?=($_GET['sector']??'')===$value?'selected':''?>><?=e($value)?></option><?php endforeach?></select></div><div class="field"><label>Usuário</label><input name="user" value="<?=e($_GET['user']??'')?>"></div><div class="field"><label>Situação</label><select name="status"><option value="">Todas</option><?php foreach($statuses as $value):?><option <?=($_GET['status']??'')===$value?'selected':''?>><?=e($value)?></option><?php endforeach?></select></div><div class="field"><label>Windows</label><select name="windows"><option value="">Todos</option><?php foreach($windows as $value):?><option <?=($_GET['windows']??'')===$value?'selected':''?>><?=e($value)?></option><?php endforeach?></select></div><div class="field"><label>Criticidade</label><select name="criticality"><option value="">Todas</option><option value="critical" <?=($_GET['criticality']??'')==='critical'?'selected':''?>>Críticos</option><option value="attention" <?=($_GET['criticality']??'')==='attention'?'selected':''?>>Atenção</option><option value="ok" <?=($_GET['criticality']??'')==='ok'?'selected':''?>>Adequados</option></select></div><button class="btn">Aplicar filtros</button><a class="btn secondary" href="/reports">Limpar</a></form><div class="actions" style="margin:16px 0"><a class="btn" href="/reports/excel<?=$exportQuery?'?'.e($exportQuery):''?>">Exportar Excel</a><a class="btn secondary" target="_blank" href="/reports/pdf<?=$exportQuery?'?'.e($exportQuery):''?>">Salvar em PDF</a><a class="btn danger" href="/reports?criticality=critical">Ver somente críticos</a></div><div class="card" style="margin-bottom:16px"><div class="card-heading"><div><h3>Recomendações prioritárias</h3><span>Resumo calculado com os equipamentos que aparecem neste relatório</span></div></div><div class="grid kpis"><div class="kpi"><strong><?=$actions['ssd']?></strong><span>Em uso precisam trocar HD por SSD</span></div><div class="kpi"><strong><?=$actions['memory']?></strong><span>Em uso precisam ampliar RAM</span></div><div class="kpi"><strong><?=$actions['replace']?></strong><span>Em uso há mais de 10 anos</span></div></div></div><div class="card table-card"><div class="card-heading"><div><h3>Equipamentos cadastrados</h3><span>Situação operacional, análise e recomendação individual</span></div></div><div class="table-wrap"><table data-table><thead><tr><th>Computador</th><th>Setor</th><th>Usuário</th><th>Situação</th><th>Ano</th><th>RAM</th><th>Windows</th><th>Discos</th><th>Criticidade</th><th>Recomendação</th></tr></thead><tbody><?php foreach($rows as $pc):?><tr><td><a href="/computers/edit?id=<?=$pc['id']?>"><?=e($pc['computer_name'])?></a></td><td><?=e($pc['sector'])?></td><td><?=e($pc['assigned_user'])?></td><td><span class="status-dot <?=report_status_class($pc['asset_status'])?>"><i></i><?=e($pc['asset_status'])?></span></td><td><?=e($pc['manufacture_year'])?><?=$pc['_age']?' ('.$pc['_age'].' anos)':''?></td><td><?=e(($pc['ram_gb']?:'—').' GB')?><br><span class="muted"><?=e($pc['_ram_layout'])?></span></td><td><?=e($pc['windows_version'])?></td><td><?=e($pc['_disks'])?></td><td><span class="badge <?=e($pc['_analysis']['level'])?>"><?=e(report_level_label($pc['_analysis']['level']))?></span><br><span class="muted"><?=e(implode(' · ',$pc['_analysis']['reasons'])?:'Sem alertas')?></span></td><td><?=e(implode(' · ',$pc['_recommendations']))?></td></tr><?php endforeach?></tbody></table></div></div><?php page_end();exit;
}
